package com.github.uscexp.jfilework.core.config;

import java.util.List;
import java.util.Map;

/**
 * Declarative binding between UI element and command invocation.
 */
public record ActionConfig(
        String id,
        String label,
        String commandId,
        Map<String, String> params,
        String shortcut,
        List<String> placement
) {
}

package com.github.uscexp.jfilework.core.config;

/**
 * Backward-compatible alias type for action-based command bindings.
 */
public record CommandBindingConfig(ActionConfig action) {
}

package com.github.uscexp.jfilework.core.config;

/**
 * UI related user configuration.
 */
public record UiConfig(
        String theme,
        boolean showHiddenFiles,
        String leftStartPath,
        String rightStartPath
) {

    public static UiConfig defaults() {
        return new UiConfig("system", false, null, null);
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import java.util.Map;

/**
 * UI callback for executing a command resolved from configuration.
 */
@FunctionalInterface
public interface CommandExecutionHandler {

    void execute(String commandId, Map<String, String> params, String actionLabel);
}

package com.github.uscexp.jfilework.ui.javafx.action;

import java.util.List;
import java.util.Map;

/**
 * Runtime action model generated from configuration.
 */
public record ConfiguredAction(
        String id,
        String label,
        String commandId,
        Map<String, String> params,
        String shortcut,
        List<String> placement,
        boolean enabled
) {
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.Scene;
import javafx.scene.input.KeyCombination;
import javafx.scene.input.KeyEvent;

import java.util.List;

/**
 * Registers and dispatches configured key bindings.
 */
public class KeyBindingService {

    public void bind(Scene scene, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        scene.addEventFilter(KeyEvent.KEY_PRESSED, event -> {
            for (ConfiguredAction action : actions) {
                if (!action.enabled() || action.shortcut() == null || action.shortcut().isBlank()) {
                    continue;
                }
                KeyCombination keyCombination;
                try {
                    keyCombination = KeyCombination.keyCombination(action.shortcut());
                } catch (IllegalArgumentException ignored) {
                    continue;
                }
                if (keyCombination.match(event)) {
                    handler.execute(action.commandId(), action.params(), action.label());
                    event.consume();
                    break;
                }
            }
        });
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.control.Menu;
import javafx.scene.control.MenuItem;
import javafx.scene.control.SeparatorMenuItem;

import java.util.List;

/**
 * Builds menu entries from configured actions.
 */
public class MenuBuilder {

    public void build(Menu fileMenu, Menu toolsMenu, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        removeDynamicItems(fileMenu);
        removeDynamicItems(toolsMenu);

        addItems(fileMenu, actions, "menu.file", handler);
        addItems(toolsMenu, actions, "menu.tools", handler);
    }

    private void addItems(Menu menu, List<ConfiguredAction> actions, String placement, CommandExecutionHandler handler) {
        boolean hasStaticItems = !menu.getItems().isEmpty();
        int inserted = 0;

        for (ConfiguredAction action : actions) {
            if (!action.placement().contains(placement)) {
                continue;
            }

            MenuItem item = new MenuItem(action.label());
            item.setId("action-" + action.id());
            item.getProperties().put("dynamicAction", Boolean.TRUE);
            item.setDisable(!action.enabled());
            item.setOnAction(event -> handler.execute(action.commandId(), action.params(), action.label()));
            menu.getItems().add(0, item);
            inserted++;
        }

        if (hasStaticItems && inserted > 0 && !menu.getItems().isEmpty()) {
            boolean alreadySeparated = menu.getItems().stream().findFirst().orElse(null) instanceof SeparatorMenuItem;
            if (!alreadySeparated) {
                SeparatorMenuItem separator = new SeparatorMenuItem();
                separator.getProperties().put("dynamicAction", Boolean.TRUE);
                menu.getItems().add(inserted, separator);
            }
        }
    }

    private static void removeDynamicItems(Menu menu) {
        menu.getItems().removeIf(item -> Boolean.TRUE.equals(item.getProperties().get("dynamicAction")));
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import com.github.uscexp.jfilework.core.command.CommandContext;

import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Resolves simple placeholders used by command parameter templates.
 */
public class ParamTemplateEngine {

    public Map<String, String> resolve(Map<String, String> templateParams, CommandContext context) {
        Map<String, String> resolved = new HashMap<>();
        if (templateParams == null) {
            return resolved;
        }

        for (Map.Entry<String, String> entry : templateParams.entrySet()) {
            resolved.put(entry.getKey(), resolveValue(entry.getValue(), context));
        }
        return resolved;
    }

    private String resolveValue(String value, CommandContext context) {
        if (value == null) {
            return "";
        }

        String result = value;
        result = result.replace("${activePane.path}", context.activeDirectory().toString());
        result = result.replace("${inactivePane.path}", context.inactiveDirectory().toString());
        result = result.replace("${selection.paths}", context.selection().paths().stream()
                .map(Path::toString)
                .collect(Collectors.joining(" ")));
        return result;
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.control.Button;
import javafx.scene.control.ToolBar;

import java.util.List;

/**
 * Builds toolbar buttons from configured actions.
 */
public class ToolbarBuilder {

    public void build(ToolBar toolBar, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        toolBar.getItems().clear();

        actions.stream()
                .filter(action -> action.placement().contains("toolbar.main"))
                .forEach(action -> {
                    Button button = new Button(action.label());
                    button.setId("action-" + action.id());
                    button.setDisable(!action.enabled());
                    button.setOnAction(event -> handler.execute(action.commandId(), action.params(), action.label()));
                    toolBar.getItems().add(button);
                });
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import com.github.uscexp.jfilework.core.command.CommandRegistry;
import com.github.uscexp.jfilework.core.config.ActionConfig;
import com.github.uscexp.jfilework.core.config.AppConfig;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.Map;

/**
 * Converts configuration entries into runtime actions and marks unknown commands as disabled.
 */
public class UiActionMapper {

    private static final Logger log = LoggerFactory.getLogger(UiActionMapper.class);

    private final CommandRegistry commandRegistry;

    public UiActionMapper(CommandRegistry commandRegistry) {
        this.commandRegistry = commandRegistry;
    }

    public List<ConfiguredAction> map(AppConfig appConfig) {
        if (appConfig == null || appConfig.actions() == null) {
            return List.of();
        }

        return appConfig.actions().stream()
                .map(this::mapAction)
                .toList();
    }

    private ConfiguredAction mapAction(ActionConfig actionConfig) {
        boolean available = commandRegistry.findById(actionConfig.commandId()).isPresent();
        if (!available) {
            log.warn("Action '{}' references unknown command '{}'", actionConfig.id(), actionConfig.commandId());
        }

        return new ConfiguredAction(
                actionConfig.id(),
                actionConfig.label(),
                actionConfig.commandId(),
                actionConfig.params() == null ? Map.of() : actionConfig.params(),
                actionConfig.shortcut() == null ? "" : actionConfig.shortcut(),
                actionConfig.placement() == null ? List.of() : actionConfig.placement(),
                available
        );
    }
}

package com.github.uscexp.jfilework.ui.javafx.controller;

import com.github.uscexp.jfilework.core.fs.FileEntry;
import com.github.uscexp.jfilework.core.fs.FileService;
import com.github.uscexp.jfilework.core.fs.FileWatcherService;
import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import com.github.uscexp.jfilework.ui.javafx.model.PaneStateViewModel;
import javafx.application.Platform;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.control.SelectionMode;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableRow;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.function.Consumer;

/**
 * Reusable controller for one file pane.
 */
public class FilePaneController {

    private static final Logger log = LoggerFactory.getLogger(FilePaneController.class);
    private static final DateTimeFormatter DATE_TIME_FORMATTER =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm").withZone(ZoneId.systemDefault());

    @FXML private Label paneTitleLabel;
    @FXML private TextField pathField;
    @FXML private TableView<FileItemViewModel> fileTable;
    @FXML private TableColumn<FileItemViewModel, String> nameColumn;
    @FXML private TableColumn<FileItemViewModel, String> sizeColumn;
    @FXML private TableColumn<FileItemViewModel, String> modifiedColumn;
    @FXML private TableColumn<FileItemViewModel, String> typeColumn;

    private final PaneStateViewModel paneState = new PaneStateViewModel();

    private FileService fileService;
    private Consumer<String> statusConsumer = ignored -> { };
    private FileWatcherService fileWatcherService;
    private String paneId = "pane";

    @FXML
    public void initialize() {
        fileTable.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);

        nameColumn.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getName()));
        sizeColumn.setCellValueFactory(cell -> {
            FileItemViewModel item = cell.getValue();
            String value = (item.isDirectory() || item.isParentLink()) ? "" : String.valueOf(item.getSize());
            return new SimpleStringProperty(value);
        });
        modifiedColumn.setCellValueFactory(cell -> {
            FileItemViewModel item = cell.getValue();
            String value = item.isParentLink() ? "" : DATE_TIME_FORMATTER.format(item.getLastModified());
            return new SimpleStringProperty(value);
        });
        typeColumn.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getType()));

        fileTable.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);
        fileTable.setRowFactory(tableView -> {
            TableRow<FileItemViewModel> row = new TableRow<>();
            row.setOnMouseClicked(event -> {
                if (event.getClickCount() == 2 && !row.isEmpty()) {
                    navigateByRow(row.getItem());
                }
            });
            return row;
        });

        fileTable.getSelectionModel().getSelectedItems().addListener((javafx.collections.ListChangeListener<FileItemViewModel>) change -> {
            List<Path> selectedPaths = new ArrayList<>();
            for (FileItemViewModel item : fileTable.getSelectionModel().getSelectedItems()) {
                selectedPaths.add(item.getPath());
            }
            paneState.getSelectedPaths().setAll(selectedPaths);
        });
    }

    public void configure(String paneId, String paneTitle, FileService fileService, Consumer<String> statusConsumer) {
        this.paneId = paneId;
        this.fileService = fileService;
        this.statusConsumer = statusConsumer == null ? ignored -> { } : statusConsumer;

        paneTitleLabel.setText(paneTitle);
        pathField.setId(paneId + "PathField");
        fileTable.setId(paneId + "FileTable");
    }

    public void navigateTo(Path path) {
        if (path == null) {
            return;
        }
        if (!Files.exists(path)) {
            statusConsumer.accept("Path does not exist: " + path);
            return;
        }
        if (!Files.isDirectory(path)) {
            statusConsumer.accept("Path is not a directory: " + path);
            return;
        }

        paneState.setCurrentPath(path.normalize());
        pathField.setText(path.normalize().toString());
        refreshCurrentDirectory();
        restartWatcher();
    }

    public PaneStateViewModel getPaneState() {
        return paneState;
    }

    public TableView<FileItemViewModel> getFileTable() {
        return fileTable;
    }

    public Path getCurrentPath() {
        return paneState.getCurrentPath();
    }

    public List<Path> getSelectedPathsForOperations() {
        return fileTable.getSelectionModel()
                .getSelectedItems()
                .stream()
                .filter(item -> !item.isParentLink())
                .map(FileItemViewModel::getPath)
                .collect(Collectors.toList());
    }

    public void refreshCurrentDirectoryView() {
        refreshCurrentDirectory();
    }

    @FXML
    private void onPathEntered() {
        String rawPath = pathField.getText();
        if (rawPath == null || rawPath.isBlank()) {
            return;
        }
        navigateTo(Paths.get(rawPath.trim()));
    }

    public void stopWatching() {
        if (fileWatcherService != null) {
            try {
                fileWatcherService.close();
            } catch (IOException e) {
                log.debug("Could not close watch service for pane {}", paneId, e);
            }
            fileWatcherService = null;
        }
    }

    private void navigateByRow(FileItemViewModel row) {
        if (row.isDirectory() || row.isParentLink()) {
            navigateTo(row.getPath());
        }
    }

    private void refreshCurrentDirectory() {
        Path path = paneState.getCurrentPath();
        if (path == null) {
            return;
        }

        try {
            List<FileItemViewModel> rows = new ArrayList<>();
            Path parent = path.getParent();
            if (parent != null) {
                rows.add(new FileItemViewModel(FileEntry.parent(parent)));
            }

            List<FileItemViewModel> fromService = fileService
                    .listDirectory(path)
                    .stream()
                    .map(FileItemViewModel::new)
                    .toList();
            rows.addAll(fromService);
            fileTable.setItems(FXCollections.observableArrayList(rows));
            statusConsumer.accept(String.format("%s: %d item(s)", paneId, rows.size()));
        } catch (IOException e) {
            log.warn("Cannot read directory {}", path, e);
            statusConsumer.accept("Cannot read directory: " + path);
            fileTable.setItems(FXCollections.observableArrayList());
        }
    }

    private void restartWatcher() {
        stopWatching();

        Path currentPath = paneState.getCurrentPath();
        if (currentPath == null) {
            return;
        }

        try {
            fileWatcherService = new FileWatcherService();
            fileWatcherService.watch(currentPath, () -> Platform.runLater(this::refreshCurrentDirectory));
        } catch (IOException e) {
            log.debug("Watch service disabled for pane {} at {}", paneId, currentPath, e);
        }
    }
}

package com.github.uscexp.jfilework.ui.javafx.controller;

import com.github.uscexp.jfilework.core.fs.FileEntry;
import com.github.uscexp.jfilework.core.fs.FileService;
import com.github.uscexp.jfilework.core.fs.FileWatcherService;
import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import com.github.uscexp.jfilework.ui.javafx.model.FileTypeIconResolver;
import com.github.uscexp.jfilework.ui.javafx.model.PaneStateViewModel;
import javafx.application.Platform;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.control.SelectionMode;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableRow;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.function.Consumer;
import java.util.Locale;

/**
 * Reusable controller for one file pane.
 */
public class FilePaneController {

    private static final Logger log = LoggerFactory.getLogger(FilePaneController.class);
    private static final DateTimeFormatter DATE_TIME_FORMATTER =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm").withZone(ZoneId.systemDefault());

    @FXML private Label paneTitleLabel;
    @FXML private TextField pathField;
    @FXML private TextField filterField;
    @FXML private TableView<FileItemViewModel> fileTable;
    @FXML private TableColumn<FileItemViewModel, String> iconColumn;
    @FXML private TableColumn<FileItemViewModel, String> nameColumn;
    @FXML private TableColumn<FileItemViewModel, String> sizeColumn;
    @FXML private TableColumn<FileItemViewModel, String> modifiedColumn;
    @FXML private TableColumn<FileItemViewModel, String> typeColumn;

    private final PaneStateViewModel paneState = new PaneStateViewModel();

    private FileService fileService;
    private Consumer<String> statusConsumer = ignored -> { };
    private FileWatcherService fileWatcherService;
    private String paneId = "pane";
    private final FileTypeIconResolver fileTypeIconResolver = new FileTypeIconResolver();
    private final ObservableList<FileItemViewModel> allRows = FXCollections.observableArrayList();

    @FXML
    public void initialize() {
        fileTable.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);

        iconColumn.setCellValueFactory(cell -> new SimpleStringProperty(fileTypeIconResolver.resolve(cell.getValue())));
        nameColumn.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getName()));
        sizeColumn.setCellValueFactory(cell -> {
            FileItemViewModel item = cell.getValue();
            String value = (item.isDirectory() || item.isParentLink()) ? "" : String.valueOf(item.getSize());
            return new SimpleStringProperty(value);
        });
        modifiedColumn.setCellValueFactory(cell -> {
            FileItemViewModel item = cell.getValue();
            String value = item.isParentLink() ? "" : DATE_TIME_FORMATTER.format(item.getLastModified());
            return new SimpleStringProperty(value);
        });
        typeColumn.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getType()));

        fileTable.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);
        fileTable.setItems(FXCollections.observableArrayList());
        fileTable.setRowFactory(tableView -> {
            TableRow<FileItemViewModel> row = new TableRow<>();
            row.setOnMouseClicked(event -> {
                if (event.getClickCount() == 2 && !row.isEmpty()) {
                    navigateByRow(row.getItem());
                }
            });
            return row;
        });

        fileTable.getSelectionModel().getSelectedItems().addListener((javafx.collections.ListChangeListener<FileItemViewModel>) change -> {
            List<Path> selectedPaths = new ArrayList<>();
            for (FileItemViewModel item : fileTable.getSelectionModel().getSelectedItems()) {
                selectedPaths.add(item.getPath());
            }
            paneState.getSelectedPaths().setAll(selectedPaths);
        });

        filterField.textProperty().addListener((ignoredObs, ignoredOldValue, ignoredNewValue) -> applyFilter());
    }

    public void configure(String paneId, String paneTitle, FileService fileService, Consumer<String> statusConsumer) {
        this.paneId = paneId;
        this.fileService = fileService;
        this.statusConsumer = statusConsumer == null ? ignored -> { } : statusConsumer;

        paneTitleLabel.setText(paneTitle);
        pathField.setId(paneId + "PathField");
        filterField.setId(paneId + "FilterField");
        fileTable.setId(paneId + "FileTable");
    }

    public void navigateTo(Path path) {
        if (path == null) {
            return;
        }
        if (!Files.exists(path)) {
            statusConsumer.accept("Path does not exist: " + path);
            return;
        }
        if (!Files.isDirectory(path)) {
            statusConsumer.accept("Path is not a directory: " + path);
            return;
        }

        paneState.setCurrentPath(path.normalize());
        pathField.setText(path.normalize().toString());
        refreshCurrentDirectory();
        restartWatcher();
    }

    public PaneStateViewModel getPaneState() {
        return paneState;
    }

    public TableView<FileItemViewModel> getFileTable() {
        return fileTable;
    }

    public Path getCurrentPath() {
        return paneState.getCurrentPath();
    }

    public List<Path> getSelectedPathsForOperations() {
        return fileTable.getSelectionModel()
                .getSelectedItems()
                .stream()
                .filter(item -> !item.isParentLink())
                .map(FileItemViewModel::getPath)
                .collect(Collectors.toList());
    }

    public void refreshCurrentDirectoryView() {
        refreshCurrentDirectory();
    }

    @FXML
    private void onPathEntered() {
        String rawPath = pathField.getText();
        if (rawPath == null || rawPath.isBlank()) {
            return;
        }
        navigateTo(Paths.get(rawPath.trim()));
    }

    public void stopWatching() {
        if (fileWatcherService != null) {
            try {
                fileWatcherService.close();
            } catch (IOException e) {
                log.debug("Could not close watch service for pane {}", paneId, e);
            }
            fileWatcherService = null;
        }
    }

    private void navigateByRow(FileItemViewModel row) {
        if (row.isDirectory() || row.isParentLink()) {
            navigateTo(row.getPath());
        }
    }

    private void refreshCurrentDirectory() {
        Path path = paneState.getCurrentPath();
        if (path == null) {
            return;
        }

        try {
            List<FileItemViewModel> rows = new ArrayList<>();
            Path parent = path.getParent();
            if (parent != null) {
                rows.add(new FileItemViewModel(FileEntry.parent(parent)));
            }

            List<FileItemViewModel> fromService = fileService
                    .listDirectory(path)
                    .stream()
                    .map(FileItemViewModel::new)
                    .toList();
            rows.addAll(fromService);
            allRows.setAll(rows);
            applyFilter();
            statusConsumer.accept(String.format("%s: %d item(s)", paneId, rows.size()));
        } catch (IOException e) {
            log.warn("Cannot read directory {}", path, e);
            statusConsumer.accept("Cannot read directory: " + path);
            allRows.clear();
            fileTable.setItems(FXCollections.observableArrayList());
        }
    }

    private void applyFilter() {
        String rawFilter = filterField.getText();
        if (rawFilter == null || rawFilter.isBlank()) {
            fileTable.setItems(FXCollections.observableArrayList(allRows));
            return;
        }

        String filter = rawFilter.toLowerCase(Locale.ROOT).trim();
        List<FileItemViewModel> filtered = allRows.stream()
                .filter(item -> item.isParentLink() || item.getName().toLowerCase(Locale.ROOT).contains(filter))
                .toList();
        fileTable.setItems(FXCollections.observableArrayList(filtered));
    }

    private void restartWatcher() {
        stopWatching();

        Path currentPath = paneState.getCurrentPath();
        if (currentPath == null) {
            return;
        }

        try {
            fileWatcherService = new FileWatcherService();
            fileWatcherService.watch(currentPath, () -> Platform.runLater(this::refreshCurrentDirectory));
        } catch (IOException e) {
            log.debug("Watch service disabled for pane {} at {}", paneId, currentPath, e);
        }
    }
}

package com.github.uscexp.jfilework.ui.javafx.model;

import java.util.Locale;

/**
 * Resolves lightweight ASCII icons for file rows.
 */
public class FileTypeIconResolver {

    public String resolve(FileItemViewModel item) {
        if (item == null) {
            return "[?]";
        }
        if (item.isParentLink()) {
            return "[..]";
        }
        if (item.isDirectory()) {
            return "[D]";
        }

        String name = item.getName();
        int dotIndex = name.lastIndexOf('.');
        if (dotIndex < 0 || dotIndex == name.length() - 1) {
            return "[F]";
        }

        String extension = name.substring(dotIndex + 1).toLowerCase(Locale.ROOT);
        return switch (extension) {
            case "txt", "md", "log", "json", "xml", "yaml", "yml", "csv" -> "[T]";
            case "java", "kt", "groovy", "js", "ts", "py", "c", "cpp", "h" -> "[C]";
            case "png", "jpg", "jpeg", "gif", "bmp", "svg" -> "[I]";
            case "zip", "jar", "7z", "rar", "tar", "gz" -> "[A]";
            case "exe", "bat", "cmd", "ps1", "sh" -> "[X]";
            default -> "[F]";
        };
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import javafx.scene.control.Button;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class DisabledActionUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useInvalidCommandConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "brokenAction",
                      "label": "Broken Action",
                      "commandId": "missing.command",
                      "params": {},
                      "shortcut": "",
                      "placement": ["toolbar.main"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-disabled", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void unknownCommandActionIsDisabledInToolbar() {
        Button button = lookup("#action-brokenAction").queryAs(Button.class);
        assertTrue(button.isDisable(), "Expected toolbar action to be disabled for unknown command");
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class FilterUiTest extends MainWindowUiTestBase {

    @Test
    void filterField_limitsVisibleRowsByName() {
        TextField filter = lookup("#leftFilterField").queryAs(TextField.class);
        clickOn(filter);
        write("alpha");

        TableView<FileItemViewModel> table = lookup("#leftFileTable").queryTableView();
        assertTrue(table.getItems().stream()
                        .filter(item -> !item.isParentLink())
                        .allMatch(item -> item.getName().toLowerCase().contains("alpha")),
                "Expected all visible rows to match filter alpha");
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import javafx.scene.control.TableView;
import javafx.scene.input.KeyCode;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.testfx.util.WaitForAsyncUtils;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class HotkeyBindingUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useHotkeyConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "copyByF9",
                      "label": "Copy with F9",
                      "commandId": "file.copy",
                      "params": { "target": "${inactivePane.path}" },
                      "shortcut": "F9",
                      "placement": ["menu.tools"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-hotkey", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void configuredHotkeyTriggersCommandWithoutMouse() {
        clickOn("#leftFileTable");
        clickOn("alpha.txt");
        push(KeyCode.F9);

        WaitForAsyncUtils.sleep(500, TimeUnit.MILLISECONDS);

        TableView<FileItemViewModel> rightTable = lookup("#rightFileTable").queryTableView();
        boolean containsCopiedFile = rightTable.getItems().stream()
                .anyMatch(item -> "alpha.txt".equals(item.getName()));
        assertTrue(containsCopiedFile, "Expected alpha.txt copied via configured F9 hotkey");
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import javafx.scene.control.TableView;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.testfx.util.WaitForAsyncUtils;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class ToolbarConfigUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useToolbarConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "copyBtn",
                      "label": "Copy via Toolbar",
                      "commandId": "file.copy",
                      "params": { "target": "${inactivePane.path}" },
                      "shortcut": "",
                      "placement": ["toolbar.main"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-toolbar", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void toolbarButtonFromConfigExecutesCommand() {
        clickOn("#leftFileTable");
        clickOn("alpha.txt");
        clickOn("#action-copyBtn");

        WaitForAsyncUtils.sleep(500, TimeUnit.MILLISECONDS);

        TableView<FileItemViewModel> rightTable = lookup("#rightFileTable").queryTableView();
        boolean containsCopiedFile = rightTable.getItems().stream()
                .anyMatch(item -> "alpha.txt".equals(item.getName()));
        assertTrue(containsCopiedFile, "Expected alpha.txt copied via configured toolbar button");
    }
}

package com.github.uscexp.jfilework.ui.javafx.model;

import com.github.uscexp.jfilework.core.fs.FileEntry;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.time.Instant;

import static org.junit.jupiter.api.Assertions.assertEquals;

class FileTypeIconResolverTest {

    private final FileTypeIconResolver resolver = new FileTypeIconResolver();

    @Test
    void resolvesParentAndDirectoryAndTypedFiles() {
        FileItemViewModel parent = new FileItemViewModel(FileEntry.parent(Path.of("C:/tmp")));
        FileItemViewModel directory = new FileItemViewModel(new FileEntry(
                Path.of("C:/tmp/folder"), "folder", true, 0L, Instant.now(), false
        ));
        FileItemViewModel textFile = new FileItemViewModel(new FileEntry(
                Path.of("C:/tmp/readme.md"), "readme.md", false, 12L, Instant.now(), false
        ));
        FileItemViewModel archive = new FileItemViewModel(new FileEntry(
                Path.of("C:/tmp/archive.zip"), "archive.zip", false, 12L, Instant.now(), false
        ));

        assertEquals("[..]", resolver.resolve(parent));
        assertEquals("[D]", resolver.resolve(directory));
        assertEquals("[T]", resolver.resolve(textFile));
        assertEquals("[A]", resolver.resolve(archive));
    }
}
